import functools


def retry(max_attempts=3):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(max_attempts):
                try:
                    return fn(*args, **kwargs)
                except Exception as e:
                    last_error = e
            raise last_error
        return wrapper
    return decorator


def validate_types(**type_map):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for param, expected_type in type_map.items():
                if param in kwargs and not isinstance(kwargs[param], expected_type):
                    raise TypeError(
                        f"Argument '{param}' must be {expected_type.__name__}, "
                        f"got {type(kwargs[param]).__name__}"
                    )
            return fn(*args, **kwargs)
        return wrapper
    return decorator
